using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
var results = new List<object>();
async Task Check(string name, Func<Task> test) { try { await test(); results.Add(new {name,passed=true,detail=""}); } catch(Exception ex) { results.Add(new {name,passed=false,detail=ex.Message}); } }
void Eq<T>(T expected,T actual) {if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}, got {actual}");}
void Throws<T>(Action f) where T:Exception {try{f();}catch(T){return;}throw new Exception($"Expected {typeof(T).Name}");}
async Task ThrowsAsync<T>(Func<Task> f) where T:Exception {try{await f();}catch(T){return;}throw new Exception($"Expected {typeof(T).Name}");}
await Check("Scope",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new LookupDb(new DbContextOptionsBuilder<LookupDb>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();db.Catalog.AddRange(new CatalogRow{Id=1,TenantId=1,Name="A",Price=20},new CatalogRow{Id=2,TenantId=1,Name="B",Price=10},new CatalogRow{Id=3,TenantId=2,Name="A",Price=30});await db.SaveChangesAsync();db.ChangeTracker.Clear();Eq("1",string.Join(",",await Kata.FindRawAsync(db,1,"A",default)));Eq(0,db.ChangeTracker.Entries().Count());});
await Check("Injection как данные",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new LookupDb(new DbContextOptionsBuilder<LookupDb>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();db.Catalog.AddRange(new CatalogRow{Id=1,TenantId=1,Name="A",Price=20},new CatalogRow{Id=2,TenantId=1,Name="B",Price=10},new CatalogRow{Id=3,TenantId=2,Name="A",Price=30});await db.SaveChangesAsync();db.ChangeTracker.Clear();var name="' OR 1=1 --";db.Catalog.Add(new CatalogRow{Id=4,TenantId=1,Name=name,Price=1});await db.SaveChangesAsync();db.ChangeTracker.Clear();Eq("4",string.Join(",",await Kata.FindRawAsync(db,1,name,default)));});
await Check("Нет результата",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new LookupDb(new DbContextOptionsBuilder<LookupDb>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();db.Catalog.AddRange(new CatalogRow{Id=1,TenantId=1,Name="A",Price=20},new CatalogRow{Id=2,TenantId=1,Name="B",Price=10},new CatalogRow{Id=3,TenantId=2,Name="A",Price=30});await db.SaveChangesAsync();db.ChangeTracker.Clear();Eq(0,(await Kata.FindRawAsync(db,1,"missing",default)).Length);});
await Check("Отмена",async()=>{await using var cn=new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new LookupDb(new DbContextOptionsBuilder<LookupDb>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();db.Catalog.AddRange(new CatalogRow{Id=1,TenantId=1,Name="A",Price=20},new CatalogRow{Id=2,TenantId=1,Name="B",Price=10},new CatalogRow{Id=3,TenantId=2,Name="A",Price=30});await db.SaveChangesAsync();db.ChangeTracker.Clear();using var c=new CancellationTokenSource();c.Cancel();await ThrowsAsync<OperationCanceledException>(()=>Kata.FindRawAsync(db,1,"A",c.Token));});
Console.WriteLine(JsonSerializer.Serialize(results));
